const WebSocket = require("ws");

class ball8 extends events {
  constructor(tokenWS) {
    super();
    this.tokenWS = tokenWS;
    this.start = Date.now();
    this.timestamp;
    this.execute();
  }

  getRandomMs() {
    return Math.floor(Math.random() * 1800000) + 600000;
  }

  execute() {
    if(!this.tokenWS) return;
    this.timestamp = this.start - this.getRandomMs();
    let updateData = {
